  dxy_beta_60          w=0.130 dir=+1  60d beta of asset returns to DXY
  time_under_water_120 w=0.107 dir=-1  days since last 120d rolling high
  vol_of_vol20x60      w=0.104 dir=+1  60d std of 20d realized vol

